function getPaymentLabel(method) {
  switch (method) {
    case 'card': return '카드 결제';
    case 'bank': return '계좌 이체';
    case 'cash': return '현금 결제';
    default: return '확인 필요';
  }
}

function getNextAction(status) {
  switch (status) {
    case 'ready': return '작업 시작';
    case 'working': return '계속 진행';
    case 'done': return '결과 확인';
    default: return '상태 문의';
  }
}
